<?php
namespace ProjectPress\Admin\Manager\ProjectManager;
use ProjectPress\Includes\Functions\Helpers\RequestHelper;
use ProjectPress\Includes\Project\Core\ProjectFieldRepository;
use ProjectPress\Includes\Project\Core\ProjectFieldService;
use ProjectPress\Includes\Project\Core\ProjectPermissions;
use ProjectPress\Includes\Project\Core\ProjectRepository;
if(!defined('ABSPATH')){exit;}
final class Fields{
 private ProjectFieldRepository $repository; private ProjectFieldService $service;
 public function __construct(){$this->repository=new ProjectFieldRepository();$this->service=new ProjectFieldService($this->repository,new ProjectRepository(),new ProjectPermissions());}
 public function render():void{$fields=$this->repository->all();$types=ProjectFieldService::types();?><div class="row g-4"><div class="col-lg-5"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Create Global Field','projectpress');?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_field_save"/><?php wp_nonce_field('projectpress_field_save');?><label class="form-label" for="field-name"><?php esc_html_e('Name','projectpress');?></label><input class="form-control" id="field-name" name="name" required/><label class="form-label mt-3" for="field-key"><?php esc_html_e('Key','projectpress');?></label><input class="form-control" id="field-key" name="key"/><label class="form-label mt-3" for="field-description"><?php esc_html_e('Description','projectpress');?></label><textarea class="form-control" id="field-description" name="description"></textarea><label class="form-label mt-3" for="field-type"><?php esc_html_e('Type','projectpress');?></label><select class="form-select" id="field-type" name="type"><?php foreach($types as $type):?><option value="<?php echo esc_attr($type);?>"><?php echo esc_html(ucwords(str_replace('_',' ',$type)));?></option><?php endforeach;?></select><div class="row mt-3"><div class="col"><div class="form-check"><input class="form-check-input" id="field-required" name="required" value="1" type="checkbox"/><label class="form-check-label" for="field-required"><?php esc_html_e('Required','projectpress');?></label></div></div><div class="col"><div class="form-check"><input class="form-check-input" id="field-enabled" name="enabled" value="1" type="checkbox" checked/><label class="form-check-label" for="field-enabled"><?php esc_html_e('Enabled','projectpress');?></label></div></div></div><button class="btn btn-primary mt-3" type="submit"><?php esc_html_e('Create Field','projectpress');?></button></form></div></div><div class="col-lg-7"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Global Fields','projectpress');?></h2><?php foreach($fields as $field):?><div class="border-bottom py-2 d-flex justify-content-between"><span><strong><?php echo esc_html($field['field_name']);?></strong><small class="d-block text-secondary"><?php echo esc_html($field['field_key']);?></small></span><span><code><?php echo esc_html($field['field_type']);?></code><?php if(!empty($field['is_required'])):?><span class="badge text-bg-warning ms-2"><?php esc_html_e('Required','projectpress');?></span><?php endif;?></span></div><?php endforeach;if(empty($fields)):?><p><?php esc_html_e('No global fields found.','projectpress');?></p><?php endif;?></div></div></div><?php }
 public function handle_save():void{check_admin_referer('projectpress_field_save');$result=$this->service->create(array('name'=>RequestHelper::text($_POST,'name',''),'key'=>RequestHelper::key($_POST,'key',''),'description'=>RequestHelper::text($_POST,'description',''),'type'=>RequestHelper::key($_POST,'type','text'),'required'=>RequestHelper::boolean($_POST,'required',false),'enabled'=>RequestHelper::boolean($_POST,'enabled',false)));$url=admin_url('admin.php?page=projectpress&group=project-manager&tab=fields');$url=is_wp_error($result)?add_query_arg('field_error',rawurlencode($result->get_error_message()),$url):add_query_arg('field_saved','1',$url);wp_safe_redirect($url);exit;}
}
